begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.fi(t text) returns uuid language sql immutable as $$select md5('member-services-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.fi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-family@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.fi('org'),'Famílias fictícias','member-services-test','active'),(pg_temp.fi('outsideorg'),'Outro fictício','family-outside','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.fi('a'),pg_temp.fi('org'),'Sede fictícia','a','headquarters'),(pg_temp.fi('b'),pg_temp.fi('org'),'Filial fictícia','b','campus');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.fi(t||'-membership'),pg_temp.fi('org'),pg_temp.fi(t),pg_temp.fi('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status,birth_date) select pg_temp.fi(t||'-person'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t),t||' pessoa fictícia','active',current_date-interval '35 years' from unnest(array['owner','member','second','unconfirmed'])t;
create function pg_temp.self(a text,d jsonb default '{}') returns jsonb language sql as $$select public.member_services(pg_temp.fi('org'),pg_temp.fi('a'),a,d)$$;
create function pg_temp.admin(a text,d jsonb default '{}') returns jsonb language sql as $$select public.member_services_admin(pg_temp.fi('org'),pg_temp.fi('a'),a,d)$$;
select ok(not has_table_privilege('authenticated','private.member_push_devices','select'),'cliente não lê tokens');
select ok(not has_function_privilege('authenticated','public.member_push_work(text,jsonb)','execute'),'cliente não processa fila');
select ok(not has_table_privilege('authenticated','private.member_digital_cards','insert'),'membro não emite carteirinha diretamente');
set local role authenticated;select pg_temp.actor('member');
select throws_ok($$select pg_temp.admin('issue',jsonb_build_object('person',pg_temp.fi('member-person'),'category','Membro','expires',(current_date+365)::text))$$,'42501','services_admin_denied','membro não emite sua carteirinha');
select is(jsonb_array_length(pg_temp.self('cards')->'items'),0,'lista inicial vazia');
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.admin('issue',jsonb_build_object('person',pg_temp.fi('member-person'),'category','Membro','expires',(current_date+365)::text))$$,'admin emite para pessoa oficial');
select throws_ok($$select pg_temp.admin('issue',jsonb_build_object('person',pg_temp.fi('outside'),'category','Membro','expires',(current_date+365)::text))$$,'42501','card_person_unavailable','não emite pessoa de outro ministério');
select pg_temp.actor('member');
select is(jsonb_array_length(pg_temp.self('cards')->'items'),1,'titular vê própria carteirinha');
select is((pg_temp.self('cards')->'items'->0->>'valid')::boolean,true,'carteirinha vigente');
select pg_temp.actor('second');select is(jsonb_array_length(pg_temp.self('cards')->'items'),0,'outra conta não lê carteirinha');
select pg_temp.actor('outside');select throws_ok($$select pg_temp.self('cards')$$,'42501','community_denied','conta de fora recusada');
select pg_temp.actor('unconfirmed');select throws_ok($$select pg_temp.self('cards')$$,'42501',null,'email não confirmado recusado');
reset role;
create function pg_temp.card() returns uuid language sql security definer as $$select id from private.member_digital_cards where organization_id=pg_temp.fi('org') limit 1$$;
create function pg_temp.code() returns uuid language sql security definer as $$select token from private.member_digital_cards where id=pg_temp.card()$$;
set local role authenticated;select pg_temp.actor('owner');
select is((pg_temp.admin('verify',jsonb_build_object('code',pg_temp.code()))->>'valid')::boolean,true,'equipe valida código vigente');
select lives_ok($$select pg_temp.admin('revoke',jsonb_build_object('id',pg_temp.card(),'version',1))$$,'revogação confirmada');
select is((pg_temp.admin('verify',jsonb_build_object('code',pg_temp.code()))->>'valid')::boolean,false,'revogação invalida código');
select throws_ok($$select pg_temp.admin('revoke',jsonb_build_object('id',pg_temp.card(),'version',1))$$,'40001','card_changed','revisão antiga não altera carteirinha');
select pg_temp.actor('member');select is(pg_temp.self('cards')->'items'->0->>'code',null,'titular não recebe código revogado');
select is((pg_temp.self('push_status')->>'configured')::boolean,false,'push sem projeto não simula configuração');
select throws_ok($$select pg_temp.self('push_register',jsonb_build_object('id',pg_temp.fi('device'),'token','ExpoPushToken[abcdefghijklmno]','project',pg_temp.fi('project'),'application','com.vinha.test'))$$,'42501','push_not_configured','push bloqueado antes da configuração');
reset role;
insert into private.member_push_apps values(pg_temp.fi('org'),pg_temp.fi('project'),'com.vinha.test',true,now());
set local role authenticated;select pg_temp.actor('member');
select throws_ok($$select pg_temp.self('push_register',jsonb_build_object('id',pg_temp.fi('device'),'token','ExpoPushToken[abcdefghijklmno]','project',pg_temp.fi('project'),'application','com.vinha.test'))$$,'42501','push_session_required','exige sessão persistente para push');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi('member'),'role','authenticated','session_id',pg_temp.fi('session'))::text,true);
select lives_ok($$select pg_temp.self('push_register',jsonb_build_object('id',pg_temp.fi('device'),'token','ExpoPushToken[abcdefghijklmno]','project',pg_temp.fi('project'),'application','com.vinha.test'))$$,'registra celular na conta');
select pg_temp.actor('second');
select throws_ok($$select pg_temp.self('push_register',jsonb_build_object('id',pg_temp.fi('device'),'token','ExpoPushToken[abcdefghijklmno]','project',pg_temp.fi('project'),'application','com.vinha.test'))$$,'40001','push_device_conflict','outra conta não sequestra dispositivo');
select pg_temp.actor('member');select lives_ok($$select pg_temp.self('push_disable',jsonb_build_object('id',pg_temp.fi('device')))$$,'membro desativa aparelho');
select pg_temp.actor('owner');
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('account'),'kind','account','name','Banco fictício'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('income'),'kind','category','name','Receita fictícia','direction','income'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('expense'),'kind','category','name','Taxa fictícia','direction','expense'));
select public.finance_digital(pg_temp.fi('org'),pg_temp.fi('a'),'purpose',jsonb_build_object('id',pg_temp.fi('purpose'),'version',0,'name','Oferta fictícia','origin','offering','account',pg_temp.fi('account'),'category',pg_temp.fi('income'),'feeCategory',pg_temp.fi('expense'),'refundCategory',pg_temp.fi('expense'),'creditCategory',pg_temp.fi('income'),'active',true));
reset role;
insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,external_id,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at,methods,payments_enabled,webhook_configured) values(pg_temp.fi('receiver'),pg_temp.fi('org'),pg_temp.fi('a'),'mercado_pago','production','configured','123','Conta fictícia',true,array[pg_temp.fi('a')],pg_temp.fi('account'),pg_temp.fi('owner'),now()+interval '1 day',array['pix'],true,true);
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select public.member_payment_publish(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('purpose'),pg_temp.fi('receiver'),true)$$,'publica finalidade com destino válido');
select pg_temp.actor('member');
select is(jsonb_array_length(public.member_payments(pg_temp.fi('org'),pg_temp.fi('a'),'list')->'purposes'),1,'membro vê finalidade publicada');
select lives_ok($$select public.member_payments(pg_temp.fi('org'),pg_temp.fi('a'),'create',jsonb_build_object('id',pg_temp.fi('order'),'purpose',pg_temp.fi('purpose'),'amount','1000'))$$,'cria pedido a partir do cadastro oficial');
select lives_ok($$select public.member_payments(pg_temp.fi('org'),pg_temp.fi('a'),'create',jsonb_build_object('id',pg_temp.fi('order'),'purpose',pg_temp.fi('purpose'),'amount','1000'))$$,'mesmo pedido é idempotente');
select throws_ok($$select public.member_payments(pg_temp.fi('org'),pg_temp.fi('a'),'create',jsonb_build_object('id',pg_temp.fi('order'),'purpose',pg_temp.fi('purpose'),'amount','2000'))$$,'40001','member_payment_conflict','não troca valor no mesmo pedido');
select pg_temp.actor('second');
select throws_ok($$select public.member_payments(pg_temp.fi('org'),pg_temp.fi('a'),'resume',jsonb_build_object('id',pg_temp.fi('order')))$$,'42501','member_payment_denied','outra conta não retoma pagamento');
select is(jsonb_array_length(public.member_payments(pg_temp.fi('org'),pg_temp.fi('a'),'list')->'orders'),0,'histórico privado por conta');
reset role;
update private.finance_purposes set origin='event' where id=pg_temp.fi('purpose');
insert into private.church_app_events(id,organization_id,unit_id,title,kind,starts_at,ends_at,capacity,status) values(pg_temp.fi('event'),pg_temp.fi('org'),pg_temp.fi('a'),'Evento pago fictício','event',now()+interval '2 days',now()+interval '3 days',1,'draft');
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select public.member_event_purchase(pg_temp.fi('org'),pg_temp.fi('a'),'price',pg_temp.fi('event'),jsonb_build_object('amount','1500','purpose',pg_temp.fi('purpose')))$$,'configura preço do rascunho');
reset role;update private.church_app_events set status='published' where id=pg_temp.fi('event');
set local role authenticated;select pg_temp.actor('member');
select throws_ok($$select public.member_agenda_self(pg_temp.fi('org'),'register',pg_temp.fi('a'),pg_temp.fi('event'))$$,'42501','member_event_payment_required','inscrição gratuita não contorna preço');
select lives_ok($$select public.member_event_purchase(pg_temp.fi('org'),pg_temp.fi('a'),'buy',pg_temp.fi('event'),jsonb_build_object('id',pg_temp.fi('event-order')))$$,'reserva última vaga e pedido financeiro');
select lives_ok($$select public.member_event_purchase(pg_temp.fi('org'),pg_temp.fi('a'),'buy',pg_temp.fi('event'),jsonb_build_object('id',pg_temp.fi('another-order')))$$,'repetição retorna pedido anterior');
select pg_temp.actor('second');select throws_ok($$select public.member_event_purchase(pg_temp.fi('org'),pg_temp.fi('a'),'buy',pg_temp.fi('event'),jsonb_build_object('id',pg_temp.fi('second-order')))$$,'40001','member_event_full','reserva segura a última vaga');
reset role;
select is((select count(*)::integer from private.church_app_registrations where event_id=pg_temp.fi('event')),0,'pedido sem prova não emite ticket');
insert into private.finance_digital_receipts(order_id,receiver_id,external_id,snapshot,occurred_at) values(pg_temp.fi('event-order'),pg_temp.fi('receiver'),'ficticio-1','{"state":"approved","gross":"1500","refunded":"0"}',now());
select is((select count(*)::integer from private.church_app_registrations where event_id=pg_temp.fi('event') and status='confirmed'),1,'prova do provedor emite ticket');
select is((select state from private.member_event_orders where order_id=pg_temp.fi('event-order')),'confirmed','pedido fica confirmado');
update private.finance_digital_receipts set snapshot='{"state":"refunded","gross":"1500","refunded":"1500"}' where order_id=pg_temp.fi('event-order');
select is((select count(*)::integer from private.church_app_registrations where event_id=pg_temp.fi('event') and status='confirmed'),0,'devolução invalida ticket');
insert into auth.sessions(id,user_id) values(pg_temp.fi('session'),pg_temp.fi('member'));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi('member'),'role','authenticated','session_id',pg_temp.fi('session'))::text,true);
set local role authenticated;
select lives_ok($$select pg_temp.self('push_register',jsonb_build_object('id',pg_temp.fi('device'),'token','ExpoPushToken[abcdefghijklmno]','project',pg_temp.fi('project'),'application','com.vinha.test'))$$,'aparelho pode reativar alertas');
reset role;
insert into private.member_publications(organization_id,unit_id,kind,title,body,published) values(pg_temp.fi('org'),pg_temp.fi('a'),'notice','Aviso fictício','Conteúdo de teste que não deve ir à tela bloqueada',true);
set local role service_role;
select ok(jsonb_array_length(public.member_push_work('claim')->'items')>0,'worker reserva novidades para sessão ativa');
select is(jsonb_array_length(public.member_push_work('claim')->'items'),0,'segunda execução não reenvia itens em processamento');
reset role;
select ok((select count(*)>0 from private.member_push_deliveries where device_id=pg_temp.fi('device') and state='sending'),'fila registra processamento durável');
delete from auth.sessions where id=pg_temp.fi('session');
set local role service_role;select public.member_push_work('claim');reset role;
select is((select enabled from private.member_push_devices where id=pg_temp.fi('device')),false,'sessão revogada desativa aparelho no worker');
select * from finish();rollback;
